code.C:
#include <stdio.h>

int main() {
    int m;
    if (scanf("%d", &m) == 1) {
        if (m >= 91) printf("Grade A\n");
        else if (m >= 76) printf("Grade B\n");
        else if (m >= 61) printf("Grade C\n");
        else printf("Grade D\n");
    }
    return 0;
}

