code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int m = sc.nextInt();
            if (m >= 91) System.out.println("Grade A");
            else if (m >= 76) System.out.println("Grade B");
            else if (m >= 61) System.out.println("Grade C");
            else System.out.println("Grade D");
        }
    }
}

code.Python3:
import sys

def main():
    s = sys.stdin.read().strip()
    if s:
        m = int(s)
        if m >= 91: print("Grade A")
        elif m >= 76: print("Grade B")
        elif m >= 61: print("Grade C")
        else: print("Grade D")

if __name__ == '__main__':
    main()

